    vc = max(range(w), key=lambda c: sum(grid[r][c] == 5 for r in range(h)))
    vrows = [r for r in range(h) if grid[r][vc] == 5]
    if len(vrows) >= 3:
        top, bottom = min(vrows), max(vrows)
        pts = [(r, c) for r in range(top, h) for c in range(vc + 1, w) if grid[r][c] != 0]
        if pts:
            r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
            c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
            tile = [grid[r][c0:c1 + 1] for r in range(r0, r1 + 1)]
            for r in range(top, bottom + 1):
                for j, value in enumerate(tile[(r-r0) % len(tile)]):
                    if grid[r][c0+j] == 0: out[r][c0+j] = value
    return out
